function Field({label,children,...props}){return <label className="field"><span>{label}</span>{children||<input {...props}/>}</label>}
function Select({label,name,items=[],optional=false,onChange,value}){const selected=value??'';return <Field label={label}><select name={name} required={!optional} onChange={onChange} value={selected}>{optional&&<option value="">Walk-in / none</option>}{items.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field>}
function Badge({children,tone='neutral'}){return <span className={'badge '+tone}>{children}</span>}
function Empty({title,description,action}){return <div className="empty"><Package size={28}/><h3>{title}</h3><p>{description}</p>{action}</div>}
function Table({head,rows,emptyText='No records yet.'}){return <div className="table-wrap"><table><thead><tr>{head.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table>{!rows.length&&<p className="table-empty">{emptyText}</p>}</div>}
