 useEffect(()=>{if(!db)return;db.auth.getSession().then(({data})=>{if(data.session){setSession(data.session);setMode('live')}});const{data}=db.auth.onAuthStateChange((event,session)=>{setSession(session);if(event==='PASSWORD_RECOVERY'){setRecovery(true);setMode('login')}else if(session)setMode('live');else setMode(m=>m==='demo'?m:'login');});return()=>data.subscription.unsubscribe()},[]);
