 const defaultProduct=initial.product_id||livestockProducts.find(x=>x.id===initial.product_id)?.id||livestockProducts.find(x=>x.division===initial.division)?.id||'';
 const [productId,setProductId]=useState(defaultProduct);
 const p=s.products.find(x=>x.id===productId)||s.products.find(x=>x.division===initial.division&&x.unit==='each'),l=s.loans.find(x=>x.id===loan),inv=s.invoices.find(x=>x.id===invoice),name=id=>s.customers.find(c=>c.id===id)?.name||'Walk-in';
