  {['opening_stock','receive'].includes(k)&&<><Field label="Age (weeks)" name="age_weeks" type="number" min="0" max="200" step="1" defaultValue="0" required/><Field label="Sex" name="sex"><select defaultValue="Unknown"><option value="Male">Male</option><option value="Female">Female</option><option value="Mixed">Mixed group</option><option value="Unknown">Unknown</option></select></Field>{k==='receive'&&<Field label="Purchase cost (E)" name="amount" type="number" min="0.01" step="0.01" required/>}<p className="hint">{k==='opening_stock'?'Opening animals already on the farm are recorded here. No supplier is required and no purchase cash is created.':'New purchases can include a purchase cost; supplier details are not required.'}</p></>}
